package com.xiaojingyu.furniture;

import java.util.EnumMap;
import java.util.Map;

import com.xiaojingyu.XiaojingyuMod;
import net.minecraft.core.Direction;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;
import org.jspecify.annotations.Nullable;

/**
 * Collision and outline shapes of the furniture cells (docs/FURNITURE.md §2): the boxes of one cell
 * facing north, in pixels (0..16), from {@link FurnitureShapes} (generated by furn's
 * web/tools/furn-mc.mjs export, interface in tmp/furn/shapes-api.md), turned by {@code facing} the same
 * way the blockstates turn the models (y rotation: north 0, east 90, south 180, west 270).
 */
final class FurnitureCollision {
    private static final double[][] FULL_BLOCK = {{0, 0, 0, 16, 16, 16}};

    private FurnitureCollision() {
    }

    /** Boxes of one cell facing north, each {x0, y0, z0, x1, y1, z1} in pixels; a full block if FurnitureShapes has none. */
    static double[][] northBoxes(String id, @Nullable String part) {
        double[][] boxes = FurnitureShapes.boxes(id, part);
        if (boxes == null) {
            XiaojingyuMod.LOGGER.warn("[xiaojingyu] FurnitureShapes has nothing for furniture {} part {}; using a full block", id, part);
            return FULL_BLOCK;
        }
        return boxes;
    }

    /** The shape of one cell for each horizontal facing (worked out once, when the block is made). */
    static Map<Direction, VoxelShape> byFacing(String id, @Nullable String part) {
        return byFacing(id, part, northBoxes(id, part));
    }

    /** The same for boxes given by the caller (round-2 furniture: FurnitureSpec cells). */
    static Map<Direction, VoxelShape> byFacing(String id, @Nullable String part, double[][] boxes) {
        Map<Direction, VoxelShape> map = new EnumMap<>(Direction.class);
        for (Direction facing : Direction.Plane.HORIZONTAL) {
            map.put(facing, shape(id, part, boxes, FurnitureShapes.quarterTurns(facing.getSerializedName())));
        }
        return map;
    }

    private static VoxelShape shape(String id, @Nullable String part, double[][] boxes, int quarterTurns) {
        VoxelShape shape = Shapes.empty();
        for (double[] raw : boxes) {
            double[] b = clamp(id, part, raw);
            if (b == null) {
                continue;
            }
            double[] t = FurnitureShapes.rotateY(b, quarterTurns);
            shape = Shapes.or(shape, Block.box(t[0], t[1], t[2], t[3], t[4], t[5]));
        }
        if (shape.isEmpty()) {
            // A cell without boxes could not be targeted or broken; keep it usable and say so.
            XiaojingyuMod.LOGGER.warn("[xiaojingyu] furniture {} part {} has no collision boxes; using a full block", id, part);
            return Shapes.block();
        }
        return shape.optimize();
    }

    /** Boxes are meant to stay inside the cell (FURNITURE.md §0: bigger models are shrunk to the cells). */
    private static double @Nullable [] clamp(String id, @Nullable String part, double[] b) {
        if (b.length != 6) {
            XiaojingyuMod.LOGGER.warn("[xiaojingyu] furniture {} part {}: box with {} numbers ignored", id, part, b.length);
            return null;
        }
        double[] c = new double[6];
        boolean changed = false;
        for (int i = 0; i < 6; i++) {
            c[i] = Math.max(0, Math.min(16, b[i]));
            changed |= c[i] != b[i];
        }
        if (changed) {
            XiaojingyuMod.LOGGER.warn("[xiaojingyu] furniture {} part {}: box outside 0..16 clamped", id, part);
        }
        if (c[0] >= c[3] || c[1] >= c[4] || c[2] >= c[5]) {
            XiaojingyuMod.LOGGER.warn("[xiaojingyu] furniture {} part {}: empty box ignored", id, part);
            return null;
        }
        return c;
    }
}
